import re
from collections import Counter
from pathlib import Path

REF = re.compile(r'day-020:L(\d+)(?:-L?(\d+))?')
root = Path("/home/user/BookMinder/.coordination")
EXCLUDE = {".coordination/day-020-repair-plan.md", ".coordination/day-020-repair-report.md"}

rows = []
for p in sorted(root.rglob("*")):
    if not p.is_file() or p.suffix not in (".md", ".yaml", ".yml", ".js", ".py"):
        continue
    rel = str(p.relative_to(root.parent))
    if rel in EXCLUDE:
        continue
    for ln, line in enumerate(p.read_text(errors="replace").splitlines(), 1):
        for m in REF.finditer(line):
            a = int(m.group(1))
            b = int(m.group(2)) if m.group(2) else a
            rows.append((rel, ln, m.group(0), a, b))


def seg(n):
    if n <= 7205:
        return "S1"
    if n <= 21809:
        return "S2"
    if n <= 31128:
        return "S3"
    if n <= 45519:
        return "S4"
    return "S5"


print(f"total refs: {len(rows)}")
print("per-interval (by start line):", dict(Counter(seg(r[3]) for r in rows)))

in_s4 = [r for r in rows if any(seg(x) == "S4" for x in (r[3], r[4]))]
print(f"refs with ANY endpoint in S4 [31129,45519]: {len(in_s4)}")
for r in in_s4:
    print("   ", r)

crossing = [r for r in rows if seg(r[3]) != seg(r[4])]
print(f"segment-crossing ranges: {len(crossing)}")
for r in crossing:
    print("   ", r)

ge = [r for r in rows if r[3] >= 45520 or r[4] >= 45520]
print(f"refs with any number >= 45520: {len(ge)}")
print("  by file:")
for f, n in sorted(Counter(r[0] for r in ge).items()):
    print(f"    {n:3d}  {f}")

nums_ge = sum(1 for r in ge for x in ({r[3], r[4]} if r[3] != r[4] else {r[3]}) if x >= 45520)
print(f"individual numbers >= 45520 (dedup per ref): {nums_ge}")
raw_ge = 0
for r in ge:
    raw_ge += sum(1 for x in ([r[3]] if r[3] == r[4] else [r[3], r[4]]) if x >= 45520)
print(f"individual numbers >= 45520 (positional): {raw_ge}")
print(f"max ref number: {max(max(r[3], r[4]) for r in rows)}")
